##
# PlantUML Server fingerprint for the asset inventory and vulnerable-component
# matching.
#
# PlantUML Server is a web application that renders UML and Graphviz diagrams
# on the fly. The official editor landing carries:
#
#   <title>PlantUML Server</title>
#   ...
#   <p>PlantUML version 1.2026.10 (Wed Nov 11 ...)</p>
#
# The footer is `Version.fullDescription()`, so the release is authoritative
# and the inventory gets a version for component matching. A standalone
# `-picoweb` server redirects the root to a sample `/plantuml/png/...` diagram
# whose PNG `tEXt` chunk says `Generated by https://plantuml.com`; that marker
# identifies the product without a release.
#
# The Asteroid CVE-2026-137955 rule reads the same landing/redirect and then
# exercises the `@startdot` path; this plugin performs no extra request.
# Version extraction is covered by both the footer and the server-header match.
##
Plugin.define do
  name "PlantUML"
  authors [
    "Ostorlab",
  ]
  version "0.1"
  description "Identifies PlantUML Server from the editor title, the release footer, or a PlantUML-generated sample PNG."
  website "https://plantuml.com"

  matches [
    {
      :search => "body",
      :regexp => %r{<title>\s*PlantUML Server\s*</title>}mi,
      :name => "PlantUML Server editor title",
    },
    {
      :search => "body",
      :version => %r{<p[^>]*>\s*PlantUML version\s+(\d{1,3}\.\d{4}\.\d{1,3})}mi,
      :name => "PlantUML release footer",
    },
    {
      :search => "headers[server]",
      :version => /PlantUML(?:\s+PicoWebServer)?\s+(\d{1,3}\.\d{4}\.\d{1,3})/i,
      :name => "PlantUML Server header version",
    },
    {
      :search => "body",
      :regexp => %r{Generated by https://plantuml\.com},
      :name => "PlantUML-generated PNG",
      :certainty => 75,
    },
  ]
end
